(function(){
 let corePromise;
 async function create(p,render,esc){
  const core=await(corePromise||=import('/nmr-core.mjs')),menu=document.createElement('details');menu.className='nmr-menu';
  menu.innerHTML='<summary aria-label="NMR settings" title="Solvent, frequency and coupling">NMR</summary><div><strong class="nmr-nucleus"></strong><label>Observed nucleus frequency (MHz)<input class="nmr-frequency" type="number" min="1" max="2000" step="any" placeholder="Required for Hz spacing"></label><fieldset><legend>Solvent</legend><div class="nmr-solvents">'+core.solvents.map(s=>'<label><input type="checkbox" data-nmr-solvent="'+s.id+'">'+s.label+'</label>').join('')+'</div></fieldset><label class="nmr-tick"><input type="checkbox" data-nmr="solventPeaks" checked>Solvent peaks / guides</label><label class="nmr-tick"><input type="checkbox" data-nmr="water">Water guide (approximate)</label><label class="nmr-tick"><input type="checkbox" data-nmr="reference">Zero reference (TMS / DSS / TSP)</label><label class="nmr-tick nmr-model-only"><input type="checkbox" data-nmr="coupling" checked>First-order splitting (T)</label><label class="nmr-tick nmr-model-only"><input type="checkbox" data-nmr="exchange" checked>Exchange-sensitive sites (T)</label><label class="nmr-tick"><input type="checkbox" data-nmr="measure">Measure two-line spacing</label><label class="nmr-tick nmr-trace-only"><input type="checkbox" data-nmr="original">Original continuous trace</label><p class="nmr-note"></p><p class="nmr-spacing"></p><div class="nmr-signals"></div><details><summary>Limits & sources</summary><p class="nmr-limits"></p><a href="'+core.nmrSources.shifts+'" target="_blank" rel="noopener noreferrer">Solvent shifts</a> · <a href="'+core.nmrSources.coupling+'" target="_blank" rel="noopener noreferrer">Solvent coupling</a> · <a href="'+core.nmrSources.principles+'" target="_blank" rel="noopener noreferrer">NMR principles</a></details></div>';
  p.querySelector('.axes-menu').before(menu);let settings={solvent:'none',frequency:0,solventPeaks:true,water:false,reference:false,coupling:true,exchange:true,measure:false,original:false};
  menu.addEventListener('toggle',()=>{if(menu.open)menu.querySelector(':scope>div').style.maxHeight=Math.max(100,innerHeight-menu.getBoundingClientRect().bottom-30)+'px'});
  const update=()=>{settings.frequency=Number(menu.querySelector('.nmr-frequency').value);for(const input of menu.querySelectorAll('[data-nmr]'))settings[input.dataset.nmr]=input.checked;if(settings.measure)p.peakMode='selected';p.selectedPeaks.clear();render()};
  menu.querySelector('.nmr-frequency').onchange=update;menu.querySelectorAll('[data-nmr]').forEach(i=>i.onchange=update);
  menu.querySelectorAll('[data-nmr-solvent]').forEach(i=>i.onchange=()=>{if(!i.checked){i.checked=true;return}settings.solvent=i.dataset.nmrSolvent;menu.querySelectorAll('[data-nmr-solvent]').forEach(other=>other.checked=other===i);update()});
  const api={
   setSource(data){if(!data)return;settings={...settings,frequency:Number(data.frequency)||(data.nmrModel?.defaultFrequency||0),solvent:data.nmrModel?'cdcl3':core.solventId(data.solvent),measure:false,original:false};menu.querySelector('.nmr-frequency').value=settings.frequency||'';menu.querySelectorAll('[data-nmr-solvent]').forEach(i=>i.checked=i.dataset.nmrSolvent===settings.solvent);menu.querySelectorAll('[data-nmr]').forEach(i=>i.checked=!!settings[i.dataset.nmr]);menu.querySelectorAll('.nmr-model-only').forEach(e=>e.hidden=!data.nmrModel||data.technique==='c13');menu.querySelector('.nmr-trace-only').hidden=!!data.nmrModel||data.kind!=='curve';menu.querySelector('.nmr-nucleus').textContent=data.technique==='c13'?'¹³C{¹H} · proton-decoupled':'¹H';menu.querySelector('.nmr-note').textContent=data.nmrModel?'T · δ and compound J are teaching assumptions. Solvent heights are assumed.':'Reference guides only. No solvent peaks are added to measured data.';menu.querySelector('.nmr-limits').textContent=data.nmrModel?data.nmrModel.limitations.join(' '):'Δν = |δ₁ − δ₂| × observed MHz. A spacing is not automatically a J assignment. Overlap, second-order effects, peak picking and referencing require review. Water/solvent positions vary with conditions. Reported source multiplicity/coupling is retained; missing values are not invented.';
   },
   view(data){if(data.nmrModel&&!(settings.frequency>0)){menu.querySelector('.nmr-note').textContent='Enter a positive observed nucleus frequency.';settings.frequency=data.nmrModel.defaultFrequency;menu.querySelector('.nmr-frequency').value=settings.frequency}const shown=core.view(data,settings);api.shown=shown;if(data.nmrModel)menu.querySelector('.nmr-note').textContent='T · δ and compound J are teaching assumptions.'+(shown.nmrSettings.strongCouplingWarning?' Overlap / strong coupling: first-order patterns are not quantitatively valid.':'');api.refreshSignals();return shown},
   original(){return settings.original},
   markers(shown,f){if(shown.nmrModel&&!settings.measure)return shown.nmrModel.signals.filter(s=>settings.exchange||!s.exchangeable).map(s=>({x:s.shift,y:1,labels:[s.label],nmrLabel:'T · δ≈'+s.shift+' · '+(settings.coupling?core.multiplicity(s):'s (splitting off)')+(shown.technique==='h1'?' · '+s.area+'H':'')+(s.couplings.length?' · J≈'+s.couplings.map(c=>c.jHz).join(', ')+' Hz':''),signalId:s.id}));if(shown.nmrLines)return shown.nmrLines.map(l=>({x:l.x,y:l.y,labels:[l.label],nmrLabel:'T line · '+l.multiplicity+' · '+l.label}));const peaks=f.detectPeaks(shown);return peaks.map(q=>{const reported=p.exportData.values?.find(v=>v.x===q.x);return {...q,nmrLabel:reported?[reported.atom,reported.multiplicity,reported.coupling].filter(Boolean).join(' · '):'Observed line; multiplicity and J not assigned'}})},
   refreshSignals(){const holder=menu.querySelector('.nmr-signals'),data=api.shown;if(!data)return;const signals=data.nmrModel?.signals.filter(s=>settings.exchange||!s.exchangeable)||[],refs=data.referenceSignals||[];holder.innerHTML=(signals.length?'<small>Signal focus · T</small>':'')+signals.map(s=>'<button type="button" data-signal="'+esc(s.id)+'">δ≈'+s.shift+' · '+core.multiplicity(s)+(data.technique==='h1'?' · '+s.area+'H':'')+(s.couplings.length?' · J≈'+s.couplings.map(c=>c.jHz).join(', ')+' Hz':'')+'<small>'+esc(s.label)+'</small></button>').join('')+(refs.length?'<small>Reference focus</small>':'')+refs.map(s=>'<button type="button" data-ref="'+esc(s.id)+'">'+esc(s.label)+' · δ≈'+s.shift+' · '+s.multiplicity+(s.couplings.length?' · J≈'+s.couplings.map(c=>c.jHz).join(', ')+' Hz':'')+'</button>').join('');holder.querySelectorAll('[data-signal],[data-ref]').forEach(b=>b.onclick=()=>{const signal=b.dataset.signal?signals.find(s=>s.id===b.dataset.signal):refs.find(s=>s.id===b.dataset.ref),lines=settings.frequency>0?core.splitSignal(b.dataset.signal&&!settings.coupling?{...signal,couplings:[]}:signal,settings.frequency):[{x:signal.shift}],pad=data.technique==='h1'?.06:1;p.viewRange=[Math.min(...lines.map(l=>l.x))-pad,Math.max(...lines.map(l=>l.x))+pad];p.selectedPeaks.clear();p.peakMode='selected';if(!settings.measure&&b.dataset.signal)p.selectedPeaks.add(signal.shift);menu.open=false;render()})},
   selected(x){if(settings.measure&&p.selectedPeaks.size>=2&&!p.selectedPeaks.has(x))p.selectedPeaks.delete(p.selectedPeaks.values().next().value)},
   decorate(svg,data){const f=window.focusSpectraData,g=f.chart(data);if(!g||!svg)return;const B=g.box;const ns='http://www.w3.org/2000/svg',append=(tag,attrs,text)=>{const e=document.createElementNS(ns,tag);for(const [k,v]of Object.entries(attrs))e.setAttribute(k,v);if(text!=null)e.textContent=text;svg.append(e);return e};
    for(const s of data.referenceSignals||[]){
     // Continuous view: solvent lines are already part of the trace; label them at their peak, as on printed spectra.
     if(data.lineshape){if(s.shift<g.lo||s.shift>g.hi||!data.nmrModel)continue;const near=data.points.filter(q=>Math.abs(q[0]-s.shift)<.05*(g.hi-g.lo)).reduce((a,q)=>q[1]>a[1]?q:a,[s.shift,0]);append('text',{x:g.xPosition(near[0])-6,y:Math.max(B.t+12,g.yPosition(near[1])-4),'text-anchor':'end',fill:'#111','font-family':'Arial, Helvetica, sans-serif','font-size':13},s.label.replace(/ · .*/,'').replace('D₂O','HOD'));continue}
     const refLines=data.nmrModel?data.referenceLines.filter(l=>l.signalId===s.id):[{x:s.shift}];for(const l of refLines){if(l.x<g.lo||l.x>g.hi)continue;const x=g.xPosition(l.x),path=data.nmrModel?'M'+x+' '+g.yPosition(0)+'V'+g.yPosition(l.y):'M'+x+' '+(B.t+48)+'V'+B.b;const node=append('path',{d:path,fill:'none',stroke:'#b38c59','stroke-width':'1.25',...(data.nmrModel?{}:{'stroke-dasharray':'4 4'})});const title=document.createElementNS(ns,'title');title.textContent=s.label+' · δ≈'+s.shift+' · '+s.multiplicity+(s.couplings.length?' · J≈'+s.couplings.map(c=>c.jHz).join(', ')+' Hz':'')+(data.nmrModel?' · T reference height':' · guide, not measured peak');node.append(title)}if(s.shift>=g.lo&&s.shift<=g.hi)append('text',{x:g.xPosition(s.shift),y:B.t+40,'text-anchor':'middle',fill:'#98794e','font-family':'Segoe UI, sans-serif','font-size':10},s.label+' ≈'+s.shift+(g.hi-g.lo<(data.technique==='c13'?10:1)?' · '+s.multiplicity+(s.couplings.length?' · J≈'+s.couplings.map(c=>c.jHz).join(', ')+' Hz':''):''))}
    const selected=[...p.selectedPeaks].filter(x=>x>=g.lo&&x<=g.hi);const spacing=settings.measure&&selected.length===2?core.lineSpacing(selected[0],selected[1],settings.frequency):null;
    menu.querySelector('.nmr-spacing').textContent=settings.measure?(spacing==null?'Select two observed lines; enter MHz to obtain Hz.':'Δν = '+spacing.toFixed(2)+' Hz · line spacing, not a confirmed J assignment.'):'';
    if(spacing!=null){const xs=selected.map(g.xPosition);append('path',{d:'M'+xs[0]+' '+(B.t+14)+'v8H'+xs[1]+'v-8',fill:'none',stroke:'#8c744c'});append('text',{x:(xs[0]+xs[1])/2,y:B.t+10,'text-anchor':'middle',fill:'#8c744c','font-size':11},'Δν = '+spacing.toFixed(2)+' Hz')}
    if(!settings.measure)for(const peak of api.markers(data,f).filter(q=>p.selectedPeaks.has(q.x))){if(peak.x<g.lo||peak.x>g.hi||!peak.nmrLabel)continue;const title=append('text',{x:Math.min(B.r-120,Math.max(B.l+120,g.xPosition(peak.x))),y:B.t-8,'text-anchor':'middle',fill:'#6c805e','font-size':10},peak.nmrLabel.length>65?peak.nmrLabel.slice(0,62)+'…':peak.nmrLabel);title.setAttribute('aria-label',peak.nmrLabel)}
   },
   csvData(original,shown){return core.csvView(original,shown)},
   metadata(){return {settings:api.shown?.nmrSettings||settings,references:api.shown?.referenceSignals||[],signals:api.shown?.nmrModel?.signals||[],lineSpacingHz:settings.measure&&p.selectedPeaks.size===2?core.lineSpacing(...p.selectedPeaks,settings.frequency):null,status:p.exportData.nmrModel?'T · compound δ/J assumptions; reference heights assumed':'Measured values preserved; guides are not measured peaks'}}
  };return api;
 }
 window.nmrControls={create};
})();
